  "diff.1p": "AI 智能体可以独自创建钱包、密封它并写入 ENS。但它无法独自把助记词取回。它的 ENS 角色只允许在一个名字上写一条记录，别无其他——这条边界由注册表强制执行，而不是靠我们的代码小心翼翼；并且在资金移动或权限扩大之前，须由人在硬件设备上确认。",
  "diff.2h": "我们无法读取你的密钥，这是代码的性质",
