  "t.nojs": "<strong>本页依靠 JavaScript 工作，而它被关闭了。</strong>这里的一切都不会被发送到任何地方，因此也没有服务端渲染的版本可供退回。<a href=\"./poc.html\">实时视图</a>和 <a href=\"https://github.com/4bridges/nextkey#readme\">README</a> 会在不运行任何东西的情况下解释同一套流程。",
