  "t.s1.phrase": "助记词",
  "t.s1.reveal": "显示五秒",
  "t.s1.risk": "这看起来像一串真实的助记词，而且不是在这里生成的。",
  "t.s1.risknote": "如果它保护着任何东西，现在就清空输入框，改按那个按钮。第 1 到第 5 步永远不会离开这个标签页——但第 6 步会写入公开的链，而链不会遗忘。",
  "t.s1.typed": "你自己的文本——本页只把它保存在内存里。",
  "t.s2.addrnote": "请留意这里缺了什么：她的授权将要存放的那条记录。这一行上的一切都是公开的，而仅凭公开值推不出那个地址——本页推不出，链上的旁观者也推不出。它需要两把私钥中的一把，因此它要到下一步才出现。",
  "t.s2.ensnote": "从黑客松部署实时读取。她从未在 NextKey 注册，也没有被征求过同意——发布一把公钥，就是全部的授权。",
  "t.s2.gen.btn": "创建一个演示授权",
