  "x.eph.v1": "این نام رازی را زیر v1 نگه داشته، پس دسترسی‌هایش در nextkey.grant.<هَشِ کلید عمومی گیرنده> می‌نشینند — نشانی‌ای که هر کسی می‌تواند حسابش کند. این همان ایرادی است که v2 برای رفعش ساخته شد، و می‌توانید پایین امتحانش کنید.",
  "x.eph.yes": "یک بار نوشته شد و هرگز جایگزین نشد. نشانی هر دسترسی روی این نام از همین یک کلید عمومی و کلید گیرنده ساخته می‌شود — و به همین دلیل است که این نشانی‌ها را نمی‌توان از هیچ داده‌ای عمومی حدس زد.",
