  "x.feed.hownote": "یک فیلتر لاگ روی یک رِزالور، و هیچ سروری: هر نوشتن متنی که انجام داده، نگه‌داشته اگر نام رکورد با nextkey. آغاز شود. مقدار همان‌طور که روی زنجیره است نشان داده می‌شود — آنجا به‌هرحال عمومی است.",
  "x.feed.living": "زنده",
  "x.feed.needname": "نامی بنویسید تا فقط نوشتن‌های همان را ببینید.",
  "x.feed.noname": "آنچه اینجا نیست، عمداً نیست. رویداد یک شناسهٔ رکورد را حمل می‌کند، نه یک نام، و رویدادی که این دو را به هم می‌بندد یک namehash دارد که رو به عقب حرکت نمی‌کند. پس این فهرست می‌تواند بگوید دسترسی‌ای داده شد و نمی‌تواند بگوید به چه کسی — که همان ادعای بقیهٔ این صفحه است، از بیرون دیده‌شده.",
