  "x.feed.nonenote": "اگر NextKey روی این استقرار جای دیگری نوشته باشد، همین‌جا باید گفته شود: بالا یک نام را جست‌وجو کنید و بعد «تازه‌سازی» را بزنید — رِزالوری که آن نام واقعاً از آن استفاده می‌کند هم زیر نظر گرفته می‌شود.",
  "x.feed.norangenote": "این محدودیت همین نقطهٔ پایانی عمومی است، نه حرفی دربارهٔ NextKey. چیزی خراب نشده و چیزی گم نشده — فقط این گره در این لحظه پرس‌وجوی لاگ را سرو نمی‌کند. یک دقیقهٔ دیگر «تازه‌سازی» را بزنید.",
  "x.feed.of": "از",
  "x.feed.oldname": "نام رِزالو می‌شود، پس ساخته شده است — فقط دورتر از آنکه یک نقطهٔ پایانی عمومی به مرورگر اجازهٔ عقب رفتن بدهد. بدون آن یک رویداد، شناسهٔ رکوردی در کار نیست، و بدون شناسه این فیلتر چیز دقیقی برای پرسیدن ندارد.",
  "x.feed.p": "هر رکوردی که NextKey می‌نویسد، تازه‌ترین اول، مستقیم از رِزالور روی Sepolia خوانده می‌شود. تا وقتی این صفحه باز است، تازه‌ها خودشان اینجا ظاهر می‌شوند — دسترسی‌ای که داده شد، دسترسی‌ای که پس گرفته شد، یک نوشته، یک راز مُهرشده. هیچ‌چیز فیلتر نمی‌شود و هیچ‌چیز نگه داشته نمی‌شود.",
  "x.feed.partial": "نام رکوردِ یک دسترسی مشتق می‌شود، پس گره نمی‌تواند آن‌ها را جدا کند — این‌ها با دست از بازه‌ای که بالا جست‌وجو شد بیرون کشیده شده‌اند. بنابراین این آن چیزی است که در آن بازه هست، نه آنچه وجود دارد.",
